function validRequestedPrice(){return requestedPrice===0||(Number.isSafeInteger(requestedPrice)&&requestedPrice>=1000&&requestedPrice<=24000);}
function renderPriceMode(){
$('price-mode').hidden=requestedPrice===0;
if(requestedPrice===0)return;
setText('price-mode-note',validRequestedPrice()?say(`Requested price held at ${usd(requestedPrice)} per job. Replay, scenario changes and shared links preserve this price until you explicitly return to searched pricing.`,`Prix demandé maintenu à ${usd(requestedPrice)} par mission. La répétition, les changements de scénario et les liens partagés conservent ce prix jusqu’à votre retour explicite à la recherche de prix.`):say('The shared link contains an unsupported requested price. No replacement price has been selected. Return explicitly to searched pricing to continue.','Le lien partagé contient un prix demandé non pris en charge. Aucun prix de remplacement n’a été choisi. Revenez explicitement à la recherche de prix pour continuer.'));
}
function updateUrl(replay=true){try{const url=new URL(location.href);url.searchParams.set('lang',language);if(result){url.searchParams.set('preset',result.input.preset);url.searchParams.set('policy',result.input.policy);url.searchParams.set('seed',result.input.seed);url.searchParams.set('price',result.input.price);if(replay)url.searchParams.set('replay','1');}history.replaceState(null,'',url);}catch{}}
function run(focus=false){if(running)return;restoreToken++;clearError();const raw=$('seed').value,seed=Number(raw);if(!raw||!Number.isSafeInteger(seed)||seed<1||seed>2147483646){showError('INVALID_SEED');$('seed').focus();return;}if(!validRequestedPrice()){showError('INVALID_PRICE');return;}running=true;$('replay').disabled=true;try{result=flywheel.runSimulation({preset:$('preset').value,policy:$('policy').value,seed,price:requestedPrice});renderPriceMode();renderResult();$('results').hidden=false;$('intro-state').hidden=true;setText('run-status',say('Simulation complete. No model or authorized operation executed.','Simulation terminée. Aucun modèle ni opération autorisée exécuté.'));updateUrl();if(focus){$('explore-title').focus();$('explore').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});}}catch(error){showError(error.message);}finally{running=false;$('replay').disabled=false;}}
function download(name,contents){const url=URL.createObjectURL(new Blob([contents],{type:'application/json;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
