$('import-replay-button').addEventListener('click',()=>$('import-replay').click());$('import-replay').addEventListener('change',async()=>{const ticket=++restoreToken,file=$('import-replay').files[0];$('import-replay').value='';if(!file)return;clearError();try{if(file.size>4096)throw Error('INVALID_IMPORT');const contents=await file.text();if(ticket!==restoreToken)return;const restored=flywheel.importSimulation(contents);if(restored.result.input.seed<1||restored.result.input.seed>2147483646)throw Error('INVALID_SEED');requestedPrice=restored.result.input.price??0;result=restored.result;$('preset').value=result.input.preset;$('policy').value=result.input.policy;$('seed').value=result.input.seed;setLanguage(restored.language);$('results').hidden=false;$('intro-state').hidden=true;setText('replay-status',say('Conditions restored and results recomputed. No historical claim or authority imported.','Conditions restaurées et résultats recalculés. Aucune revendication historique ni autorité importée.'));updateUrl();}catch(error){if(ticket===restoreToken)showError(error.message);}});
