// Discovery planning uses the existing Alpha project codec. It grants no authority.
const discoveryIds=['needs','purpose','existing','gap','why','restriction','structure','alternatives','construction','arrangement','experiment','falsifier','checkpoint'];
let discoveryOrigin='user-supplied hypothesis',discoveryBase=null,discoveryImported=null,discoveryVersion=0,discoverySavedVersion=-1,discoverySavedText=null;
function discoveryInput(){
const value={};for(const id of discoveryIds)value[id]=$('discovery-'+id).value.trim();
value.cap=$('discovery-cap').value.trim()?Number($('discovery-cap').value):NaN;value.decision=$('discovery-decision').value;
return value;
}
// BEGIN DISCOVERY PLANNING HELPERS
function discoveryPlanFields(input,origin,sourceHash){
const limits={needs:600,purpose:600,existing:500,gap:500,why:400,restriction:600,structure:500,alternatives:600,construction:500,arrangement:500,experiment:500,falsifier:500,checkpoint:500};
for(const [key,maximum]of Object.entries(limits))if(typeof input[key]!=='string'||input[key].length>maximum)throw Error('INVALID_DISCOVERY');
if(!input.needs.trim()||!input.purpose.trim()||!Number.isSafeInteger(input.cap)||input.cap<0||input.cap>1000000||!['continue','revise','stop'].includes(input.decision))throw Error('INVALID_DISCOVERY');
if(typeof origin!=='string'||origin.length>120||typeof sourceHash!=='string'||!/^([0-9a-f]{64})$/.test(sourceHash))throw Error('INVALID_DISCOVERY');
const known=text=>text.trim()||'Unspecified; remains a hypothesis.';
return {goal:'Needs and beneficiaries: '+input.needs+'\nOriginal purpose and requirements: '+input.purpose,
currentApproach:'Existing approaches: '+known(input.existing)+'\nBinding restriction: '+known(input.restriction),
alternative:'Possible shared structure: '+known(input.structure)+'\nDifferent approaches: '+known(input.alternatives)+'\nProposed construction: '+known(input.construction),
target:'Unresolved gap: '+known(input.gap)+'\nDecisive experiment: '+known(input.experiment)+'\nFalsifier: '+known(input.falsifier),
evidence:'Planning provenance: '+origin+'. No autonomous discovery, execution or commercial evidence is established.\nWhy now: '+known(input.why)+'\nArrangement hypothesis: '+known(input.arrangement)+'\nSource: '+sourceHash,
budget:'Assumed exploration ceiling USD '+input.cap+'. Planning decision: '+input.decision+'. No funds, permission, contract or authority.\nDependencies, checkpoint and stop: '+known(input.checkpoint)};
}
function discoveryMissing(input){
const missing=Object.keys({needs:0,purpose:0,existing:0,gap:0,why:0,restriction:0,structure:0,construction:0,arrangement:0,experiment:0,falsifier:0,checkpoint:0}).filter(key=>!input[key]?.trim());
const alternatives=(input.alternatives??'').split('\n').map(s=>s.trim()).filter(Boolean);
if(new Set(alternatives).size<2)missing.push('different formulations');
return missing;
}
// END DISCOVERY PLANNING HELPERS
function renderDiscovery(){
const value=discoveryInput(),empty=say('Still to specify','À préciser');
setText('discovery-provenance',discoveryImported?say(`Imported Alpha project: ${discoveryBase.opportunities.length} recorded hypotheses. Its original history is preserved. Editing starts an additional hypothesis. No authority was restored.`,`Projet Alpha importé : ${discoveryBase.opportunities.length} hypothèses enregistrées. L’historique original est préservé. Une modification commence une hypothèse supplémentaire. Aucune autorité restaurée.`):discoveryOrigin.startsWith('supplied')?say('The example’s needs, shared structure, instrument and arrangement are supplied by its authors. Selecting them is not autonomous discovery. Edit any assumption for your own bounded exploration.','Les besoins, la structure commune, l’instrument et l’arrangement de cet exemple sont fournis par les auteurs. Les sélectionner n’est pas une découverte autonome. Modifiez toute hypothèse pour votre exploration bornée.'):say('Your entries are planning assumptions until independently supported. A complete business case is not required to record a useful exploratory question.','Vos saisies restent des hypothèses jusqu’à leur confirmation indépendante. Un dossier d’affaires complet n’est pas requis pour enregistrer une question exploratoire utile.'));
if(discoveryImported){const p=discoveryImported;pairs($('discovery-witness'),[[say('Original goal / requirements','But / critères originaux'),p.goal],[say('Existing restriction','Restriction existante'),p.currentApproach],[say('Proposed replacement','Remplacement proposé'),p.alternative],[say('Experiment and falsifier','Expérience et réfutation'),p.target],[say('Recorded evidence scope','Portée des preuves'),p.evidence],[say('Bounded decision','Décision bornée'),p.budget],[say('Inherited authority','Autorité héritée'),say('NONE','AUCUNE')]]);}else pairs($('discovery-witness'),[[say('Original purpose','But original'),value.purpose||empty],[say('Binding restriction','Restriction décisive'),value.restriction||empty],[say('Replacement hypothesis','Hypothèse de remplacement'),value.construction||value.structure||empty],[say('Falsifying observation','Observation réfutante'),value.falsifier||empty],[say('Planning choice','Choix de planification'),({continue:say('Continue bounded exploration','Continuer l’exploration bornée'),revise:say('Revise before construction','Réviser avant de construire'),stop:say('Stop; preserve resources','Arrêter ; préserver les ressources')})[value.decision]],[say('Assumed ceiling / committed cash','Plafond supposé / fonds engagés'),(Number.isSafeInteger(value.cap)?usd(value.cap):empty)+' / '+usd(0)]]);
const missing=discoveryMissing(value);setText('discovery-completeness',discoveryImported?say('This is an imported historical hypothesis. Technical qualification, buyer commitments, complete costs and current authority require their own evidence.','Il s’agit d’une hypothèse historique importée. Qualification technique, engagements acheteurs, coûts complets et autorité actuelle exigent leurs propres preuves.'):missing.length?say(`${missing.length} planning ingredients remain unspecified. Record the question now; reduce uncertainty before claiming construction, demand or advantage.`,`${missing.length} ingrédients de planification restent à préciser. Enregistrez la question dès maintenant ; réduisez l’incertitude avant de revendiquer construction, demande ou avantage.`):say('The planning fields are populated. Their content is not validated evidence; preserve the original requirements during every experiment.','Les champs de planification sont remplis. Leur contenu n’est pas une preuve validée ; préservez les critères originaux à chaque expérience.'));
table($('discovery-comparisons'),[say('Reference','Référence'),say('Question','Question')],[['H',say('Equivalent human service: commercial price reference','Service humain équivalent : référence commerciale')],['U → E',say('Same model and budget: does expert operation improve accepted work?','Même modèle et budget : l’usage expert améliore-t-il le travail accepté ?')],['E → E+',say('Same expert starting point: does the new retained method add value after costs?','Même base experte : la méthode retenue ajoute-t-elle de la valeur après coûts ?')]],say('Two separate Operational Alpha comparisons','Deux comparaisons distinctes d’Alpha opérationnel'));
}
function discoveryError(code){if(code==='FULL_PROJECT'){setText('discovery-error',say('This project already contains twelve hypotheses. Preserve its export and choose New exploration for a separate project.','Ce projet contient déjà douze hypothèses. Conservez son export puis choisissez Nouvelle exploration pour créer un projet distinct.'));$('discovery-error').hidden=false;return;}setText('discovery-error',say('Enter the useful needs and original requirements, whole exploration dollars from 0 to 1,000,000, and bounded text. Open only an existing Alpha project JSON up to 128 KB.','Saisissez les besoins utiles et les critères originaux, un plafond entier de 0 à 1 000 000 USD et des textes bornés. Ouvrez uniquement un projet Alpha JSON existant d’au plus 128 Ko.'));$('discovery-error').hidden=false;}
function clearDiscoveryError(){$('discovery-error').hidden=true;setText('discovery-error','');}
function discoveryChanged(){discoveryOpenToken++;discoveryVersion++;discoveryImported=null;if(discoveryOrigin.startsWith('supplied'))discoveryOrigin='supplied fixture edited by the user';else discoveryOrigin='user-supplied hypothesis';clearDiscoveryError();setText('discovery-status',say('Unsaved planning changes. Export a project to preserve them.','Modifications de planification non sauvegardées. Exportez le projet pour les conserver.'));renderDiscovery();}
for(const id of discoveryIds)$('discovery-'+id).addEventListener('input',discoveryChanged);
for(const id of ['cap','decision'])$('discovery-'+id).addEventListener('input',discoveryChanged);
$('discovery-example').addEventListener('click',()=>{
discoveryOpenToken++;
const examples={
needs:say('A clinic needs critical-load continuity. A water operator needs pump availability. A shelter needs safe emergency power. Each has a different useful service purpose; these are supplied synthetic needs.','Une clinique veut maintenir ses charges critiques. Un réseau d’eau veut garder ses pompes disponibles. Un refuge veut une alimentation de secours sûre. Ces finalités distinctes sont des besoins synthétiques fournis.'),
purpose:say('Preserve each participant’s original load, outage duration, safety constraints and acceptance checks. Do not replace uninterrupted critical service with an easier average-energy target.','Préserver la charge, la durée de panne, les contraintes de sécurité et les critères de chaque participant. Ne pas remplacer la continuité critique par une cible d’énergie moyenne plus facile.'),
existing:say('REopt and conventional engineering already support resilience studies. Give every comparator the same methods and formulations.','REopt et l’ingénierie conventionnelle permettent déjà ces études. Donner les mêmes méthodes et formulations à tous les comparateurs.'),
gap:say('No independently validated unresolved gap is established by this historical fixture. Investigate one before selecting a flagship.','Cette régression historique n’établit aucune lacune irrésolue validée indépendamment. En rechercher une avant de choisir le projet phare.'),
why:say('This preserved example tests record integrity, not a new technical opportunity.','Cet exemple conservé teste l’intégrité des dossiers, pas une nouvelle possibilité technique.'),
restriction:say('Separate custom resilience studies repeat expensive scenario modeling. Hypothesis: independently useful services may share part of the engineering and verification work.','Les études de résilience sur mesure répètent une modélisation coûteuse. Hypothèse : des services utiles distincts pourraient partager une partie de l’ingénierie et de la vérification.'),
structure:say('A common scenario representation and checker may serve different critical-load purposes, with customer-specific constraints retained. Conventional optimization is an available building block.','Une représentation des scénarios et un vérificateur communs pourraient servir plusieurs finalités en préservant les contraintes propres aux clients. L’optimisation conventionnelle est disponible.'),
alternatives:say('Independent competent conventional studies.\nA shared verification instrument with separate customer adaptations.\nConditional pooled commissioning with and without shared construction.','Études conventionnelles compétentes séparées.\nInstrument de vérification commun avec adaptations distinctes.\nCommande groupée conditionnelle, avec et sans construction partagée.'),
construction:say('Prototype a reusable scenario compiler and independent requirement checker. Produce inspectable schedules and refusal reasons; never infer demand from shared structure.','Prototyper un compilateur de scénarios et un vérificateur indépendant. Produire des plans inspectables et des motifs de refus ; ne pas déduire la demande de la structure commune.'),
arrangement:say('Invite separate needs evidence before any offer. Compare outside options, conditional participation, construction prefunding, delivery dates, refunds and shared technical failure. No participant has committed.','Demander des preuves de besoins distincts avant toute offre. Comparer alternatives, participation conditionnelle, préfinancement, échéances, remboursements et risque technique commun. Aucun engagement reçu.'),
experiment:say('At equal requirements, compare technical construction alone, coordination alone and both. Recheck held-out service purposes; measure complete adaptation, verification and coordination costs.','À critères égaux, comparer construction seule, coordination seule et combinaison. Revérifier des finalités nouvelles ; mesurer tous les coûts d’adaptation, de vérification et de coordination.'),
falsifier:say('Reject the claimed advantage if an original service requirement fails, a strong ordinary method is equally efficient after costs, or independently supported participation cannot finance the package.','Rejeter l’avantage si un critère original échoue, si une méthode conventionnelle forte est aussi efficace après coûts ou si la participation étayée ne peut financer l’ensemble.'),
checkpoint:say('After the first independently checked prototype, stop if original requirements cannot be preserved or the evidence is insufficient. Assess the complementary package only within this ceiling; do not spend hypothetical future receipts.','Après le premier prototype vérifié, arrêter si les critères ne peuvent être préservés ou si les preuves restent insuffisantes. Évaluer l’ensemble complémentaire dans ce plafond ; ne pas dépenser de recettes hypothétiques.')};
for(const id of discoveryIds)$('discovery-'+id).value=examples[id];$('discovery-cap').value='5000';$('discovery-decision').value='continue';discoveryVersion++;discoveryOrigin='supplied synthetic planning fixture';discoveryImported=null;clearDiscoveryError();setText('discovery-status',say('Supplied example loaded. Nothing was discovered, executed, committed or authorized.','Exemple fourni chargé. Aucune découverte, exécution, obligation ni autorisation créée.'));renderDiscovery();
});
$('discovery-review').addEventListener('click',()=>{clearDiscoveryError();try{project.planOpportunity(discoveryPlanFields(discoveryInput(),discoveryOrigin,SOURCE_HASH));renderDiscovery();setText('discovery-status',say('Planning brief checked for bounded fields. Its technical, commercial and authority claims remain unqualified.','Champs bornés du dossier vérifiés. Ses prétentions techniques, commerciales et d’autorité restent non qualifiées.'));}catch{discoveryError();}});
$('discovery-export').addEventListener('click',()=>{clearDiscoveryError();try{
if(discoverySavedVersion!==discoveryVersion||!discoverySavedText){const fields=discoveryPlanFields(discoveryInput(),discoveryOrigin,SOURCE_HASH),base=discoveryBase||project.createProject({name:say('Blue Sky opportunity','Occasion Blue Sky'),goal:fields.goal});if(base.opportunities.length>=12)throw Error('FULL_PROJECT');const next=project.addOpportunity(base,fields);discoverySavedText=project.serializeProject(next);discoveryBase=next;discoverySavedVersion=discoveryVersion;}
download('blue-sky-alpha-project.json',discoverySavedText);setText('discovery-status',say(`Alpha project exported with ${discoveryBase.opportunities.length} hypotheses. Open it in the existing Alpha workspace; no authority or accepted result is inherited.`,`Projet Alpha exporté avec ${discoveryBase.opportunities.length} hypothèses. Ouvrez-le dans l’espace Alpha existant ; aucune autorité ni acceptation héritée.`));
}catch(error){discoveryError(error.message);}});
let discoveryOpenToken=0;
$('discovery-open-button').addEventListener('click',()=>$('discovery-open').click());
$('discovery-open').addEventListener('change',async()=>{const ticket=++discoveryOpenToken,file=$('discovery-open').files[0];$('discovery-open').value='';if(!file)return;clearDiscoveryError();try{if(file.size>131072)throw Error('INVALID_DISCOVERY');const contents=await file.text();if(ticket!==discoveryOpenToken)return;if(contents.length>131072)throw Error('INVALID_DISCOVERY');const restored=project.inspectProject(contents);discoveryBase=restored;discoveryImported=restored.opportunities.at(-1)||null;discoveryVersion++;discoverySavedVersion=discoveryVersion;discoverySavedText=project.serializeProject(restored);for(const id of discoveryIds)$('discovery-'+id).value='';$('discovery-cap').value='0';$('discovery-decision').value='continue';discoveryOrigin='imported historical Alpha project';renderDiscovery();setText('discovery-status',say('Original project history restored for inspection. Export without editing preserves it; new entries append a separate hypothesis. No permission restored.','Historique original restauré pour inspection. Un export sans modification le préserve ; de nouvelles saisies ajoutent une hypothèse distincte. Aucune permission restaurée.'));}catch{if(ticket===discoveryOpenToken)discoveryError();}});
$('discovery-new').addEventListener('click',()=>{discoveryOpenToken++;discoveryVersion++;discoveryBase=null;discoveryImported=null;discoverySavedVersion=-1;discoverySavedText=null;discoveryOrigin='user-supplied hypothesis';for(const id of discoveryIds)$('discovery-'+id).value='';$('discovery-cap').value='0';$('discovery-decision').value='continue';clearDiscoveryError();renderDiscovery();setText('discovery-status',say('New unsaved exploration. Existing downloaded projects remain separate.','Nouvelle exploration non sauvegardée. Les projets déjà téléchargés restent distincts.'));$('discovery-needs').focus();});
function renderDiscoveryEvidence(){
renderOpportunityInvestigation();
if(typeof DISCOVERY_EVIDENCE==='undefined'||!$('discovery-recorded'))return;
const report=DISCOVERY_EVIDENCE;if(!report.summary||!Array.isArray(report.lineage)){$('discovery-recorded').hidden=true;return;}
$('discovery-recorded').hidden=false;
setText('discovery-recorded-scope',say('Recorded hybrid computation: local construction, execution and finite checks. Needs and invention ingredients are researcher supplied; model, ENS and monetary attestations are fictional. Actual frontier calls and customer collections are zero. Complete actual cost is unknown; the recorded decision rejects admission and stops.','Calcul hybride enregistré : construction locale, exécution et vérifications finies. Besoins et ingrédients d’invention fournis par les chercheurs ; attestations de modèle, ENS et monétaires fictives. Aucun appel frontière ni encaissement client réel. Coût réel complet inconnu ; la décision refuse l’admission et arrête.'));
const stages={'Opportunity':say('Opportunity','Occasion'),'Transformation':say('Transformation','Transformation'),'Construction and delivery':say('Construction and delivery','Construction et livraison'),'Commercial arrangement':say('Commercial arrangement','Arrangement commercial'),'Retention and successor':say('Retention and successor','Rétention et succession')};
table($('discovery-recorded-stages'),[say('Stage','Étape'),say('Recorded status','Statut enregistré'),say('Evidence','Preuve'),say('Boundary','Limite')],report.lineage.map(row=>[stages[row.stage]||row.stage,row.status,row.evidence,row.limitation]),say('Source-bound local opportunity lineage','Parcours local de l’occasion lié aux sources'));
const witness=report.connected?.witness?.spec;
if(witness)pairs($('discovery-recorded-witness'),[[say('Original useful purpose','But utile original'),witness.purpose.useful_purpose],[say('Original requirements','Critères originaux'),witness.purpose.acceptance_criteria.join(' · ')],[say('Binding restriction','Restriction décisive'),witness.binding_restriction],[say('Why removable','Pourquoi elle pourrait être levée'),witness.removable_basis],[say('Replacement','Remplacement'),witness.replacement],[say('Operation in the original setting','Fonctionnement dans le cadre original'),witness.operation_in_original_setting],[say('Falsifying observation','Observation réfutante'),witness.falsifying_observation],[say('Inherited acceptance / authority','Acceptation / autorité héritées'),say('NONE · fresh mission recheck and separate grant required','AUCUNE · nouvelle vérification et autorisation séparée requises')]]);
setText('discovery-recorded-json',JSON.stringify(report,null,2));
}
function renderOpportunityInvestigation(){
if(typeof OPPORTUNITY_EVIDENCE==='undefined')return;
const dossier=OPPORTUNITY_EVIDENCE.candidate_dossier,select=$('opportunity-candidate'),chosen=select.value;
select.replaceChildren();for(const candidate of dossier){const option=document.createElement('option');option.value=candidate.id;option.textContent=language==='fr'?candidate.title_fr:candidate.title_en;select.appendChild(option);}if(dossier.some(row=>row.id===chosen))select.value=chosen;
const candidate=dossier.find(row=>row.id===select.value);if(!candidate)return;
const fields=[['beneficiary','Beneficiary','Bénéficiaire'],['useful_outcome','Useful outcome','Résultat utile'],['existing_approaches','Established approaches','Approches établies'],['remaining_gap','Remaining gap','Lacune restante'],['why_now','Why now','Pourquoi maintenant'],['construction','Proposed construction','Construction proposée'],['decisive_experiment','Decisive experiment','Expérience décisive'],['commercial_mechanism','Commercial mechanism','Mécanisme commercial'],['falsifier','Falsifier','Réfutation'],['decision','Recorded decision','Décision enregistrée']];
pairs($('opportunity-case'),fields.map(([key,en,fr])=>[say(en,fr),candidate[key]]).concat([[say('Primary evidence / source language: English','Preuves primaires / langue des sources : anglais'),candidate.evidence.join(' · ')]]));
const episode=OPPORTUNITY_EVIDENCE.episodes[$('opportunity-episode').value],after=episode.after;
pairs($('opportunity-result'),[[say('Before the additional observation','Avant l’observation supplémentaire'),episode.before.result||say('Unresolved','Non résolu')],[say('Requested read','Lecture demandée'),episode.before.next_probe||say('None can distinguish the states','Aucune ne distingue les états')],[say('After / finite-model result','Après / résultat du modèle fini'),after.result||after.reason],[say('Observation work units / monetary cost','Unités de lecture / coût monétaire'),after.query_units_spent+' / '+say('unknown','inconnu')],[say('Artifact identity','Identité de l’artefact'),after.problem_digest],[say('Retry permission / inherited authority','Permission de réessayer / autorité héritée'),say('NONE / NONE','AUCUNE / AUCUNE')]]);
setText('opportunity-controls',say('The strong direct-audit control matches. Missing observations remain unresolved; unexpected evidence invalidates the finite model. No graph premium or Operational Alpha is measured.','Le contrôle par audit direct donne le même résultat. Sans observation, l’incertitude reste ; une preuve inattendue invalide le modèle fini. Aucun supplément de valeur du graphe ni Alpha opérationnel n’est mesuré.'));
}
$('opportunity-candidate').addEventListener('change',renderOpportunityInvestigation);
$('opportunity-episode').addEventListener('change',renderOpportunityInvestigation);
$('opportunity-evidence-export').addEventListener('click',()=>{if(typeof OPPORTUNITY_EVIDENCE!=='undefined')download('agi-alpha-opportunity-investigation.json',JSON.stringify(OPPORTUNITY_EVIDENCE,null,2));});

$('discovery-evidence-export').addEventListener('click',()=>{if(typeof DISCOVERY_EVIDENCE!=='undefined')download('agi-alpha-discovery-evidence.json',JSON.stringify(DISCOVERY_EVIDENCE,null,2));});

const initialQuery=new URLSearchParams(location.search);for(const [key,id]of [['preset','preset'],['policy','policy']]){const value=initialQuery.get(key);if([...$(id).options].some(o=>o.value===value))$(id).value=value;}const initialSeed=Number(initialQuery.get('seed'));if(Number.isSafeInteger(initialSeed)&&initialSeed>=1&&initialSeed<=2147483646)$('seed').value=initialSeed;const initialPrice=initialQuery.get('price');if(initialPrice!==null)requestedPrice=initialPrice.trim()?Number(initialPrice):NaN;setLanguage(initialQuery.get('lang')==='fr'?'fr':'en');if(!validRequestedPrice())showError('INVALID_PRICE');else if(initialQuery.get('replay')==='1')run();
